$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'src/HousePrototype.psm1') -Force -DisableNameChecking
$s=New-HouseSession $PSScriptRoot 6001;foreach($room in $s.HouseContent.rooms){$s.State.Player.Location=$room.id;foreach($entry in @(Get-HouseNounTable $s|Where-Object kind -eq 'object')){if($entry.salience-notin@('dominant','notable','texture')){throw "Missing salience: $($room.id)/$($entry.id)"}}}
$s.State.Player.Location='cellar';$packet=New-HouseNarrationPacket $s 'look around' @('The cellar is visible.') @() @();$case=[pscustomobject]@{location='Cellar';time='8:00 PM';weather='rain';actor='Armand';action_type='look';target='cellar';degree='resolved';facts=@('The cellar is visible.');visible=@($packet.visible_referents.display_name);visible_referents=$packet.visible_referents;authorial_intent=$packet.authorial_intent};Import-Module (Join-Path $PSScriptRoot 'src/NarrationPacket.psm1') -Force;$formatted=Format-NarrationPacket (ConvertTo-NarrationPacket $case) facts
if($formatted-notmatch'Compose by salience'-or$formatted-notmatch'\[dominant\].*rope'){throw 'Salience did not reach narrator composition instructions.'}
Write-Host 'House salience tests passed.'
